const snapshot = await tools.browser_snapshot({});
const elements = unwrap(snapshot).elements;
const localityInput = elements.find(e => e.name === 'Locality' || e.name.toLowerCase().includes('locality'));
const loadRecordBtn = elements.find(e => e.name === 'Load record' || e.name.toLowerCase().includes('load'));

if (localityInput) {
  await tools.browser_fill({ref: localityInput.ref, value: '福州'});
}

if (loadRecordBtn) {
  await tools.browser_click({ref: loadRecordBtn.ref});
}

// After clicking, we need a new snapshot to ensure we have the latest refs if needed,
// but the task says 'use latest refs' and 'fill then click'.
// Since we need to wait for '鱼丸' next, we can proceed.
return {
  locality_ref: localityInput?.ref,
  load_btn_ref: loadRecordBtn?.ref
};
